"use client";
import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
  CardFooter,
} from "@/components/ui/card";
import { Slider } from "@/components/ui/slider";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { ScrollArea } from "@/components/ui/scroll-area";
import { motion, AnimatePresence } from "framer-motion";
import { Info, Settings, Layers, X } from "lucide-react";
import ThreeScene from "./ThreeScene";

// Компонент для відображення логів
function ConsolePanel({ logs }: { logs: string[] }) {
  return (
    <ScrollArea className="h-[200px] w-full rounded-md border border-neutral-700 p-2 bg-black text-green-400 font-mono text-xs">
      {logs.map((log, i) => (
        <div key={i} className="py-0.5">
          {log}
        </div>
      ))}
    </ScrollArea>
  );
}

// Компонент для налаштувань шару
function LayerSettings({
  label,
  description,
  checked,
  onCheckedChange,
}: {
  label: string;
  description: string;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
}) {
  return (
    <div className="flex items-center justify-between py-2">
      <div className="space-y-0.5">
        <Label className="text-sm font-medium">{label}</Label>
        <CardDescription className="text-xs text-neutral-400">
          {description}
        </CardDescription>
      </div>
      <Switch checked={checked} onCheckedChange={onCheckedChange} />
    </div>
  );
}

// Основний компонент інтерфейсу карти
export default function MapInterface() {
  const [isRightOpen, setIsRightOpen] = useState(false);
  const [activeTab, setActiveTab] = useState("settings");
  const [settings, setSettings] = useState({
    zoom: 5,
    buildings: true,
    traffic: false,
    weather: false,
    labels: true,
    terrain: false,
    nightMode: false,
  });

  const [logs, setLogs] = useState<string[]>([]);

  // Перехоплення логів консолі
  useEffect(() => {
    const originalLog = console.log;
    console.log = (...args: any[]) => {
      setLogs((prev) => {
        const newLogs = [...prev, args.map((a) => String(a)).join(" ")];
        return newLogs.slice(-100);
      });
      originalLog(...args);
    };
    return () => {
      console.log = originalLog;
    };
  }, []);

  // Обробка зміни налаштувань
  const handleChange = (key: string, value: any) => {
    setSettings((prev) => ({ ...prev, [key]: value }));
    console.log(`Змінено ${key}: ${value}`);
  };

  // Налаштування для вкладок
  const tabs = [
    {
      value: "settings",
      icon: <Settings className="h-4 w-4" />,
      label: "Налаштування",
      content: (
        <div className="space-y-4">
          <div className="space-y-2">
            <Label className="text-sm font-medium">Масштаб</Label>
            <Slider
              defaultValue={[settings.zoom]}
              min={1}
              max={10}
              step={1}
              value={[settings.zoom]}
              onValueChange={(value) => handleChange("zoom", value[0])}
            />
            <CardDescription className="text-xs text-neutral-400">
              Поточне значення: {settings.zoom}
            </CardDescription>
          </div>

          <div className="space-y-3">
            <LayerSettings
              label="Будівлі"
              description="Відображення 3D моделей будівель на карті"
              checked={settings.buildings}
              onCheckedChange={(checked) => handleChange("buildings", checked)}
            />
            <LayerSettings
              label="Трафік"
              description="Показує поточну ситуацію з рухом транспорту"
              checked={settings.traffic}
              onCheckedChange={(checked) => handleChange("traffic", checked)}
            />
            <LayerSettings
              label="Погода"
              description="Відображення метеоумов у реальному часі"
              checked={settings.weather}
              onCheckedChange={(checked) => handleChange("weather", checked)}
            />
            <LayerSettings
              label="Позначки"
              description="Показує назви вулиць та об'єктів"
              checked={settings.labels}
              onCheckedChange={(checked) => handleChange("labels", checked)}
            />
            <LayerSettings
              label="Рельєф"
              description="Відображення височин та низин на карті"
              checked={settings.terrain}
              onCheckedChange={(checked) => handleChange("terrain", checked)}
            />
            <LayerSettings
              label="Нічний режим"
              description="Зміна кольорової схеми для зручності вночі"
              checked={settings.nightMode}
              onCheckedChange={(checked) => handleChange("nightMode", checked)}
            />
          </div>
        </div>
      ),
    },
    {
      value: "info",
      icon: <Info className="h-4 w-4" />,
      label: "Інформація",
      content: (
        <div className="space-y-4">
          <CardDescription className="text-sm">
            <p className="mb-2">
              <strong>Поточні налаштування:</strong>
            </p>
            <ul className="space-y-1 pl-4 text-xs list-disc">
              <li>Масштаб: {settings.zoom}</li>
              <li>Будівлі: {settings.buildings ? "Увімкнено" : "Вимкнено"}</li>
              <li>Трафік: {settings.traffic ? "Увімкнено" : "Вимкнено"}</li>
              <li>Погода: {settings.weather ? "Увімкнено" : "Вимкнено"}</li>
              <li>Позначки: {settings.labels ? "Увімкнено" : "Вимкнено"}</li>
              <li>Рельєф: {settings.terrain ? "Увімкнено" : "Вимкнено"}</li>
              <li>
                Нічний режим: {settings.nightMode ? "Увімкнено" : "Вимкнено"}
              </li>
            </ul>
          </CardDescription>

          <div className="pt-2">
            <Label className="text-sm font-medium">Консоль JS</Label>
            <ConsolePanel logs={logs} />
          </div>
        </div>
      ),
    },
  ];

  return (
    <div className="w-full h-full flex overflow-hidden bg-neutral-900 text-white relative">
      {/* Ліва панель з вкладками */}
      <Card className="w-64 h-full flex flex-col bg-neutral-800 border-r border-neutral-700 rounded-none">
        <CardHeader className="flex flex-row items-center gap-2 border-b border-neutral-700 pb-4">
          <Layers className="h-5 w-5" />
          <CardTitle className="text-lg">Карта</CardTitle>
        </CardHeader>

        <Tabs
          defaultValue="settings"
          value={activeTab}
          onValueChange={setActiveTab}
          className="flex-1 flex flex-col"
        >
          <TabsList className="grid w-full grid-cols-2 mx-2 my-2">
            {tabs.map((tab) => (
              <TabsTrigger key={tab.value} value={tab.value} className="gap-2">
                {tab.icon}
                {tab.label}
              </TabsTrigger>
            ))}
          </TabsList>

          {tabs.map((tab) => (
            <TabsContent
              key={tab.value}
              value={tab.value}
              className="flex-1 overflow-y-auto p-2"
            >
              {tab.content}
            </TabsContent>
          ))}
        </Tabs>
      </Card>

      {/* Основна область карти */}
      <div className="flex-1 relative">
        <ThreeScene settings={settings} />
      </div>

      {/* Права висувна панель */}
      <AnimatePresence>
        {isRightOpen && (
          <motion.div
            initial={{ x: 400 }}
            animate={{ x: 0 }}
            exit={{ x: 400 }}
            transition={{ type: "spring", stiffness: 200, damping: 22 }}
            className="w-80 h-full bg-neutral-900 border-l border-neutral-700 p-4 absolute right-0 top-0 flex flex-col gap-4 shadow-xl rounded-l-2xl overflow-y-auto z-10"
          >
            <div className="flex justify-between items-center">
              <CardTitle className="text-lg">Деталі</CardTitle>
              <Button
                variant="ghost"
                size="icon"
                onClick={() => setIsRightOpen(false)}
                className="h-8 w-8"
              >
                <X className="h-4 w-4" />
              </Button>
            </div>

            <ScrollArea className="flex-1 pr-2">
              <div className="space-y-4">
                <Card>
                  <CardHeader>
                    <CardTitle className="text-sm">Поточні параметри</CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-2 text-sm">
                    <p>
                      <strong>Масштаб:</strong> {settings.zoom}
                    </p>
                    <p>
                      <strong>Будівлі:</strong>{" "}
                      {settings.buildings ? "Увімкнено" : "Вимкнено"}
                    </p>
                    <p>
                      <strong>Трафік:</strong>{" "}
                      {settings.traffic ? "Увімкнено" : "Вимкнено"}
                    </p>
                    <p>
                      <strong>Погода:</strong>{" "}
                      {settings.weather ? "Увімкнено" : "Вимкнено"}
                    </p>
                    <p>
                      <strong>Позначки:</strong>{" "}
                      {settings.labels ? "Увімкнено" : "Вимкнено"}
                    </p>
                    <p>
                      <strong>Рельєф:</strong>{" "}
                      {settings.terrain ? "Увімкнено" : "Вимкнено"}
                    </p>
                    <p>
                      <strong>Нічний режим:</strong>{" "}
                      {settings.nightMode ? "Увімкнено" : "Вимкнено"}
                    </p>
                  </CardContent>
                </Card>

                <Card>
                  <CardHeader>
                    <CardTitle className="text-sm">Консоль</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <ConsolePanel logs={logs} />
                  </CardContent>
                </Card>
              </div>
            </ScrollArea>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
