import * as THREE from "three";

export function tempToColor(temp, minTemp = -30, maxTemp = 45) {
  const t = Math.max(0, Math.min(1, (temp - minTemp) / (maxTemp - minTemp)));
  const color = new THREE.Color();

  if (t < 0.2) {
    color.lerpColors(
      new THREE.Color(0x0000ff),
      new THREE.Color(0x00ffff),
      t / 0.2
    );
  } else if (t < 0.4) {
    color.lerpColors(
      new THREE.Color(0x00ffff),
      new THREE.Color(0x00ff00),
      (t - 0.2) / 0.2
    );
  } else if (t < 0.6) {
    color.lerpColors(
      new THREE.Color(0x00ff00),
      new THREE.Color(0xffff00),
      (t - 0.4) / 0.2
    );
  } else if (t < 0.8) {
    color.lerpColors(
      new THREE.Color(0xffff00),
      new THREE.Color(0xff8800),
      (t - 0.6) / 0.2
    );
  } else {
    color.lerpColors(
      new THREE.Color(0xff8800),
      new THREE.Color(0xff0000),
      (t - 0.8) / 0.2
    );
  }

  return color;
}

export function humidityToColor(humidity, minHumidity = 0, maxHumidity = 100) {
  const t = Math.max(
    0,
    Math.min(1, (humidity - minHumidity) / (maxHumidity - minHumidity))
  );
  const color = new THREE.Color();

  if (t < 0.33) {
    color.lerpColors(
      new THREE.Color(0xffeecc),
      new THREE.Color(0xaaddff),
      t / 0.33
    );
  } else if (t < 0.66) {
    color.lerpColors(
      new THREE.Color(0xaaddff),
      new THREE.Color(0x4488ff),
      (t - 0.33) / 0.33
    );
  } else {
    color.lerpColors(
      new THREE.Color(0x4488ff),
      new THREE.Color(0x0033aa),
      (t - 0.66) / 0.34
    );
  }

  return color;
}
